-- =============================================================================
-- NEXA · 011310 · Büroflächen: up to 1.000 seats, paid step by step (ADR-218)
-- =============================================================================
-- The owner: "Man soll mehr Plätze für Mitarbeiter haben. Bis zu 1000. Aber das kostet zu upgraden."
--
-- Seats of a player company were legal form (garage 2 … AG 100) + 10 × expansion level (ADR-083/191, × 1,8 in price
-- per level) + the headquarters (ADR-208, 410 at the Mega-Campus). The expansion level is priced for market and
-- capacity, so 1.000 seats were out of reach (an AG with the full headquarters needed 49 levels, the 49th costing
-- 10^19 €). New: a separate line "Büroflächen" (startups.offices, src/lib/sim/offices.ts) with 12 steps and 500 seats,
-- exponential prices (0,25 Mio. € … 600 Mio. €, 1,55 Mrd. € in all), gated by legal form (steps 1–3 from the GmbH,
-- 4–12 AG) and company value (company_worth_cents, 2 Mio. € … 2,5 Mrd. €). All seats together are capped at
-- maxTotalSeats = 1.000. Every bought office seat costs rent in the hourly close (10 € per seat and hour, from the
-- free cash like the subsidiaries), so empty seats are not free.
--
-- Changed (latest full definitions copied):
--   company_max_employees   from 20261204010010_world_map.sql, + office seats, capped at maxTotalSeats
--   company_seats_sync      from 20261204007350_company_growth_path.sql, + office_level (trigger column list too)
--   company_seats_guard     unchanged (it calls company_max_employees)
--   company_growth_path     from 20261204007350_company_growth_path.sql, + office level and seats
--   world_hour_costs        from 20261204010010_world_map.sql, + the office rent first (for every player company,
--                           placed or not; listed_hour_costs calls it for every player company inside its own guard)
-- New: office_level, company_office_step, company_office_seats, company_offices_json, get_company_offices(),
--      buy_company_office(request_id).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. State
-- ---------------------------------------------------------------------------
alter table public.player_companies add column if not exists office_level integer not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'player_companies_office_level_check') then
    alter table public.player_companies add constraint player_companies_office_level_check check (office_level >= 0);
  end if;
end;
$$;
comment on column public.player_companies.office_level is 'Bought Büroflächen steps (ADR-218, startups.offices.steps).';

-- ---------------------------------------------------------------------------
-- B. Rules (src/lib/sim/offices.ts)
-- ---------------------------------------------------------------------------
-- step n (1-based) of startups.offices.steps, null past the last one
create or replace function public.company_office_step(p_n integer)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select case when p_n >= 1 then public.config_jsonb('startups', '{offices,steps}') -> (p_n - 1) end;
$$;

-- office seats after `level` bought steps (officeSeats)
create or replace function public.company_office_seats(p_level integer)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum((s ->> 'seats')::integer), 0)::integer
    from jsonb_array_elements(coalesce(public.config_jsonb('startups', '{offices,steps}'), '[]'::jsonb))
         with ordinality x(s, n)
   where x.n <= greatest(0, coalesce(p_level, 0));
$$;

-- places: tier + expansion (ADR-083/191) + the seats of the headquarters (ADR-208) + offices (ADR-218), capped
-- (latest definition from 20261204010010_world_map.sql)
create or replace function public.company_max_employees(p_company uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select least(public.config_double('startups', '{offices,maxTotalSeats}', 1000)::integer,
               coalesce((public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer, 0)
               + public.config_double('startups', '{expansion,employeesPerLevel}', 10)::integer * pc.expansion_level
               + coalesce((select sum((public.world_hq_tier_cfg(t.n) ->> 'seats')::integer)
                             from public.company_locations l, generate_series(1, l.hq_tier) t(n)
                            where l.company_id = p_company), 0)::integer
               + public.company_office_seats(pc.office_level))
    from public.player_companies pc where pc.company_id = p_company;
$$;
comment on function public.company_max_employees(uuid) is
  'Places for players and AI workers (maxEmployees of the tier + employeesPerLevel × expansion level, ADR-083, + the '
  'seats of every headquarters tier reached, ADR-208, + the Büroflächen, ADR-218), at most offices.maxTotalSeats.';

-- a new legal form, expansion level or office step updates the places (latest definition from 7350)
create or replace function public.company_seats_sync()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.tier is distinct from old.tier or new.expansion_level is distinct from old.expansion_level
     or new.office_level is distinct from old.office_level then
    update public.companies set max_employees = public.company_max_employees(new.company_id) where id = new.company_id;
  end if;
  return new;
end;
$$;
comment on function public.company_seats_sync() is
  'Trigger (ADR-191, ADR-218): a new legal form, expansion level or office step updates the places of the company.';

drop trigger if exists company_seats_sync on public.player_companies;
create trigger company_seats_sync
  after update of tier, expansion_level, office_level on public.player_companies
  for each row execute function public.company_seats_sync();

-- The whole path (latest definition from 7350) plus the office line.
create or replace function public.company_growth_path(p_company uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
           'stage', s.stage,
           'stages', s.total,
           'expansion_level', pc.expansion_level,
           'step', s.stage + pc.expansion_level,
           'next', case when s.stage < s.total then jsonb_build_object('kind', 'stage', 'n', s.stage + 1)
                        else jsonb_build_object('kind', 'level', 'n', pc.expansion_level + 1) end,
           'can_expand', public.company_can_expand(pc.tier),
           'next_cost_cents', case when public.company_can_expand(pc.tier)
                                   then public.company_expansion_cost_cents(pc.expansion_level) end,
           'max_employees', public.company_max_employees(pc.company_id),
           'office_level', pc.office_level,
           'office_seats', public.company_office_seats(pc.office_level))
    from public.player_companies pc
    cross join lateral (
      select public.company_stage(pc.company_id) as stage,
             jsonb_array_length(coalesce(public.company_product(pc.company_id) -> 'stages', '[]'::jsonb)) as total) s
   where pc.company_id = p_company;
$$;
comment on function public.company_growth_path(uuid) is
  'Wachstum & Ausbau as one path (ADR-191): stage, stages, expansion level, step = stage + level, next, next cost, places; '
  'office level and seats (ADR-218).';

-- ---------------------------------------------------------------------------
-- C. Read model for the card "Büroflächen"
-- ---------------------------------------------------------------------------
create or replace function public.company_offices_json(p_company uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  pc       public.player_companies;
  v_steps  jsonb := coalesce(public.config_jsonb('startups', '{offices,steps}'), '[]'::jsonb);
  v_next   jsonb;
  v_max    integer := public.config_double('startups', '{offices,maxTotalSeats}', 1000)::integer;
  v_seats  integer;
  v_worth  bigint;
  v_free   bigint;
  v_hq     integer;
  v_block  text;
begin
  select * into pc from public.player_companies where company_id = p_company;
  if pc.company_id is null then
    return null;
  end if;
  v_next := public.company_office_step(pc.office_level + 1);
  v_seats := public.company_max_employees(p_company);
  v_worth := coalesce(public.company_worth_cents(p_company), 0);
  select coalesce(a.balance_cents, 0) - pc.unpaid_cents into v_free
    from public.ledger_accounts a where a.owner_company_id = p_company and a.kind = 'company_cash';
  v_free := coalesce(v_free, 0);
  select coalesce(sum((public.world_hq_tier_cfg(t.n) ->> 'seats')::integer), 0)::integer into v_hq
    from public.company_locations l, generate_series(1, l.hq_tier) t(n) where l.company_id = p_company;
  -- officeBlock: all bought, cap reached, legal form, company value, free cash
  v_block := case when v_next is null then 'max_level'
                  when v_seats >= v_max then 'seats_max'
                  when not coalesce(v_next -> 'tiers', '[]'::jsonb) ? pc.tier then 'legal_form'
                  when v_worth < (v_next ->> 'minWorthCents')::bigint then 'worth'
                  when v_free < (v_next ->> 'costCents')::bigint then 'cash' end;
  return jsonb_build_object(
    'level', pc.office_level,
    'steps', jsonb_array_length(v_steps),
    'tier', pc.tier,
    'seats', jsonb_build_object(
      'tier', coalesce((public.company_tier_cfg(pc.tier) ->> 'maxEmployees')::integer, 0),
      'expansion', public.config_double('startups', '{expansion,employeesPerLevel}', 10)::integer * pc.expansion_level,
      'headquarters', coalesce(v_hq, 0),
      'offices', public.company_office_seats(pc.office_level),
      'total', v_seats,
      'max', v_max,
      'used', public.company_headcount(p_company)),
    'rent_cents_per_hour', public.company_office_seats(pc.office_level)::bigint
                           * public.config_double('startups', '{offices,rentCentsPerSeatPerHour}', 1000)::bigint,
    'worth_cents', v_worth,
    'free_cash_cents', v_free,
    'next', case when v_next is not null then jsonb_build_object(
              'n', pc.office_level + 1,
              'seats', (v_next ->> 'seats')::integer,
              'cost_cents', (v_next ->> 'costCents')::bigint,
              'min_worth_cents', (v_next ->> 'minWorthCents')::bigint,
              'tiers', coalesce(v_next -> 'tiers', '[]'::jsonb)) end,
    'block', v_block);
end;
$$;
comment on function public.company_offices_json(uuid) is
  'Büroflächen of a player company (ADR-218): level, seats by source, rent, next step and why it is blocked.';

create or replace function public.get_company_offices()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return public.company_offices_json(public.require_own_company());
end;
$$;
comment on function public.get_company_offices() is 'RPC (founder): the Büroflächen of the own company (ADR-218).';

-- ---------------------------------------------------------------------------
-- D. Buying the next step
-- ---------------------------------------------------------------------------
create or replace function public.buy_company_office(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_player  uuid;
  v_replay  jsonb;
  pc        public.player_companies;
  v_step    jsonb;
  v_cost    bigint;
  v_free    bigint;
  v_n       integer;
begin
  v_company := public.require_own_company();
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_company_office');
  if v_replay is not null then
    return v_replay;
  end if;
  select * into pc from public.player_companies where company_id = v_company for update;
  v_n := pc.office_level + 1;
  v_step := public.company_office_step(v_n);
  if v_step is null then
    perform public.api_error('office_max_level');
  end if;
  if public.company_max_employees(v_company) >= public.config_double('startups', '{offices,maxTotalSeats}', 1000)::integer then
    perform public.api_error('office_seats_max');
  end if;
  if not coalesce(v_step -> 'tiers', '[]'::jsonb) ? pc.tier then
    perform public.api_error('office_legal_form');
  end if;
  if coalesce(public.company_worth_cents(v_company), 0) < (v_step ->> 'minWorthCents')::bigint then
    perform public.api_error('office_worth');
  end if;
  v_cost := (v_step ->> 'costCents')::bigint;
  -- free cash: open bills come first (as expand_company)
  select a.balance_cents - pc.unpaid_cents into v_free
    from public.ledger_accounts a where a.owner_company_id = v_company and a.kind = 'company_cash' for update;
  if coalesce(v_free, 0) < v_cost then
    perform public.api_error('insufficient_funds');
  end if;
  if v_cost > 0 then
    perform public.ledger_transfer(public.company_cash_account(v_company), public.ledger_system_account('treasury'), v_cost,
                                   'company_costs', 'Büroflächen: Stufe ' || v_n, 'company', v_company,
                                   'office:' || v_company::text || ':' || v_n, v_player, jsonb_build_object('cat', 'office'));
  end if;
  update public.player_companies set office_level = v_n where company_id = v_company;  -- company_seats_sync
  perform public.company_system_message(v_company, 'Büroflächen Stufe ' || v_n || ' für ' || public.format_eur(v_cost)
                                                   || ': ' || (v_step ->> 'seats') || ' Plätze mehr.');
  return public.request_complete(v_player, p_request_id,
                                 jsonb_build_object('offices', public.company_offices_json(v_company)));
end;
$$;
comment on function public.buy_company_office(uuid) is
  'RPC (founder, ADR-218): buys the next Büroflächen step from the free company cash (to the treasury). Errors '
  'office_max_level, office_seats_max, office_legal_form, office_worth, insufficient_funds.';

-- ---------------------------------------------------------------------------
-- E. Rent in the hourly close: world_hour_costs (latest definition from 20261204010010_world_map.sql) books the rent
--    of the office seats first, for every player company; then subsidiaries and the Standortgebühr as before.
-- ---------------------------------------------------------------------------
create or replace function public.world_hour_costs(p_company uuid, p_hour_start timestamptz, p_key text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  l       public.company_locations;
  pc      public.player_companies;
  lb      public.country_lobby;
  v_acc   uuid;
  v_left  bigint;
  v_subs  bigint := 0;
  v_pay   bigint;
  v_rev   bigint;
  v_fee   bigint := 0;
  v_lead  uuid;
  v_name  text;
  v_rent  bigint := 0;
  s       record;
begin
  select * into pc from public.player_companies where company_id = p_company;
  -- ADR-218: rent of the office seats, from the free cash only (never a bill)
  if coalesce(pc.office_level, 0) > 0 then
    v_acc := public.company_cash_account(p_company);
    select greatest(0, a.balance_cents) into v_left from public.ledger_accounts a where a.id = v_acc for update;
    v_rent := least(public.company_office_seats(pc.office_level)::bigint
                    * public.config_double('startups', '{offices,rentCentsPerSeatPerHour}', 1000)::bigint,
                    coalesce(v_left, 0));
    if v_rent > 0 then
      perform public.ledger_transfer(v_acc, public.ledger_system_account('households'), v_rent, 'company_costs',
                                     'Büroflächen: Miete', 'company', p_company, p_key || ':office:rent',
                                     pc.founder_id, jsonb_build_object('cat', 'office'));
    end if;
  end if;
  select * into l from public.company_locations where company_id = p_company for update;
  if l.company_id is null then
    return v_rent;
  end if;
  v_acc := public.company_cash_account(p_company);
  select greatest(0, a.balance_cents) into v_left from public.ledger_accounts a where a.id = v_acc;
  v_left := coalesce(v_left, 0);
  -- subsidiaries: what the cash allows, never a bill
  for s in select x.opened_at from public.company_subsidiaries x where x.company_id = p_company loop
    v_subs := v_subs + public.world_subsidiary_hourly_cost(extract(epoch from (p_hour_start - s.opened_at)) / 3600.0);
  end loop;
  v_pay := least(v_subs, v_left);
  if v_pay > 0 then
    perform public.ledger_transfer(v_acc, public.ledger_system_account('households'), v_pay, 'company_costs',
                                   'Tochterfirmen: laufende Kosten', 'company', p_company, p_key || ':world:subs',
                                   pc.founder_id, jsonb_build_object('cat', 'world'));
    v_left := v_left - v_pay;
  end if;
  -- Standortgebühr: the leader of the HQ country (another company, still leading) takes its share of the own revenue
  v_lead := public.country_market_leader(l.country_key);
  select * into lb from public.country_lobby where country_key = l.country_key;
  if v_lead is not null and v_lead <> p_company and lb.leader_company_id = v_lead and lb.fee_bps > 0 then
    select coalesce(sum(e.amount_cents), 0) into v_rev
      from public.ledger_transactions t join public.ledger_entries e on e.transaction_id = t.id and e.account_id = v_acc
     where t.idempotency_key = p_key || ':revenue';
    v_fee := least(floor(greatest(0, v_rev) * least(lb.fee_bps, public.cfg_num(public.world_cfg(), '{lobby,maxFeeBps}', 300)) / 10000.0)::bigint,
                   v_left);
    if v_fee > 0 then
      v_name := coalesce(public.country_cfg(l.country_key) ->> 'name', l.country_key);
      perform public.ledger_transfer(v_acc, public.company_cash_account(v_lead), v_fee, 'company_costs',
                                     'Standortgebühr ' || v_name, 'company', p_company, p_key || ':world:fee',
                                     pc.founder_id, jsonb_build_object('cat', 'world', 'leader', v_lead));
      update public.company_locations set fees_paid_cents = fees_paid_cents + v_fee where company_id = p_company;
      update public.company_locations set fees_received_cents = fees_received_cents + v_fee where company_id = v_lead;
      update public.country_lobby set collected_cents = collected_cents + v_fee, updated_at = now()
       where country_key = l.country_key;
    end if;
  end if;
  return v_rent + v_pay + v_fee;
end;
$$;
comment on function public.world_hour_costs(uuid, timestamptz, text) is
  'Hourly close (ADR-208, ADR-218): rent of the office seats, running costs of the subsidiaries and the Standortgebühr '
  'to the market leader, all from the free cash only; returns the sum (counted as fixed costs of the hour).';

-- ---------------------------------------------------------------------------
-- F. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.company_office_step(integer)', 'public.company_office_seats(integer)', 'public.company_max_employees(uuid)',
    'public.company_seats_sync()', 'public.company_growth_path(uuid)', 'public.company_offices_json(uuid)',
    'public.world_hour_costs(uuid, timestamptz, text)', 'public.get_company_offices()', 'public.buy_company_office(uuid)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
  grant execute on function public.company_growth_path(uuid) to service_role;
  grant execute on function public.company_offices_json(uuid) to service_role;
  grant execute on function public.get_company_offices() to authenticated, service_role;
  grant execute on function public.buy_company_office(uuid) to authenticated, service_role;
end;
$$;

-- ===== supabase/updates/20261204011320_player_stock_tiers.sql =====
-- ===== idempotent copy of migrations/20261204011320_player_stock_tiers.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 011320 · Player stocks climb out of the penny stock class (ADR-218)
-- =============================================================================
-- The owner: "Und man soll auch höher kommen als nur eine Pennystock-Aktie."
--
-- Every player stock was listed as 'penny' (ipo_escrow) and stayed there for good: the deepest slippage
-- (playerImpact.depthCentsPer100Bps.penny: 1.000 € move the price 1 %), the widest spread and the strongest noise, even
-- for a company worth billions. Now companies.tier of a listed player company follows its market cap
-- (company_worth_cents, ADR-203) on the ladder trading.playerStockTiers (src/lib/sim/stock-tier.ts):
--   penny (0) → smallcap (50 Mio. €) → midcap (200 Mio. €) → largecap (1 Mrd. €) → bluechip (3 Mrd. €)
-- Up to the highest rung reached; down one rung only below 80 % of the own threshold (hysteresis); at least 6 hours
-- between two changes. player_stock_tiers_run() checks every 10 minutes (cron nexa-player-stock-tiers), writes the new
-- tier, posts stock news (Mr. Doodle reads news_items) and notifies the founder ('stock_tier').
--
-- Every lookup keyed by companies.tier reads the new keys from game_config (impact depth in market_order_plan and the
-- tick, half spread, tick noise, AI weight, borrow fee), so no market function is rewritten.
--
-- NULL tier made explicit: the order plan and the tick read a missing tier as 'midcap'. A trigger now gives every
-- player company with a security an explicit tier ('penny' until the first check), and existing rows are repaired.
-- New enum values (011300) are used only inside PL/pgSQL bodies, cast from text at run time.
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- ---------------------------------------------------------------------------
-- A. State
-- ---------------------------------------------------------------------------
create table if not exists public.player_stock_tiers (
  company_id        uuid primary key references public.companies (id) on delete cascade,
  tier              text not null,
  changed_at        timestamptz,
  checked_at        timestamptz not null default now(),
  market_cap_cents  bigint not null default 0,
  peak_tier         text not null
);
alter table public.player_stock_tiers enable row level security;
revoke all on public.player_stock_tiers from public, anon, authenticated;
comment on table public.player_stock_tiers is
  'Stock tier of each listed player company (ADR-218): last change (hysteresis clock), last check, highest tier. Internal.';

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('stock_tier', 'company', 'Aktienklasse', 'Deine Aktie steigt in eine höhere Klasse auf oder fällt zurück.',
        'notif_company', true, true, false, 216)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. No player stock without an explicit tier
-- ---------------------------------------------------------------------------
create or replace function public.company_player_tier_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not new.is_ai and new.security_id is not null and new.tier is null then
    new.tier := 'penny';
  end if;
  return new;
end;
$$;
comment on function public.company_player_tier_guard() is
  'Trigger (ADR-218): a player company with a security always has an explicit stock tier (penny until the first check).';

drop trigger if exists company_player_tier_guard on public.companies;
create trigger company_player_tier_guard
  before insert or update of tier, security_id on public.companies
  for each row execute function public.company_player_tier_guard();

update public.companies set tier = 'penny' where not is_ai and security_id is not null and tier is null;

-- ---------------------------------------------------------------------------
-- C. Rules (src/lib/sim/stock-tier.ts)
-- ---------------------------------------------------------------------------
create or replace function public.player_stock_tier_cfg()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(public.config_jsonb('trading', '{playerStockTiers}'),
                  '{"ladder": [{"tier": "penny", "minMarketCapCents": 0, "label": "Pennystock"}], "downBps": 8000,
                    "minHoursBetweenChanges": 6, "checkEveryMinutes": 10}'::jsonb);
$$;

-- nextStockTier: up to the highest rung reached, down one rung below downBps of the own threshold, nothing within
-- minHoursBetweenChanges of the last change (null hours = never changed). An unknown tier counts as the bottom rung.
create or replace function public.player_stock_tier_next(p_current text, p_cap numeric, p_hours double precision, p_cfg jsonb)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_ladder jsonb := coalesce(p_cfg -> 'ladder', '[]'::jsonb);
  v_n      integer := jsonb_array_length(coalesce(p_cfg -> 'ladder', '[]'::jsonb));
  v_rung   integer;
  v_up     integer;
begin
  if v_n = 0 then
    return coalesce(p_current, 'penny');
  end if;
  select (x.n - 1)::integer into v_rung from jsonb_array_elements(v_ladder) with ordinality x(r, n) where x.r ->> 'tier' = p_current;
  v_rung := coalesce(v_rung, 0);
  if p_current is not null and p_hours is not null
     and p_hours < coalesce((p_cfg ->> 'minHoursBetweenChanges')::double precision, 6) then
    return v_ladder -> v_rung ->> 'tier';
  end if;
  v_up := v_rung;
  while v_up + 1 < v_n and coalesce(p_cap, 0) >= (v_ladder -> (v_up + 1) ->> 'minMarketCapCents')::numeric loop
    v_up := v_up + 1;
  end loop;
  if v_up > v_rung then
    return v_ladder -> v_up ->> 'tier';
  end if;
  if v_rung > 0 and coalesce(p_cap, 0) < (v_ladder -> v_rung ->> 'minMarketCapCents')::numeric
                                         * coalesce((p_cfg ->> 'downBps')::numeric, 8000) / 10000 then
    return v_ladder -> (v_rung - 1) ->> 'tier';
  end if;
  return v_ladder -> v_rung ->> 'tier';
end;
$$;
comment on function public.player_stock_tier_next(text, numeric, double precision, jsonb) is
  'nextStockTier (ADR-218): the stock tier after a check, with hysteresis and the minimum time between changes.';

create or replace function public.player_stock_tier_rung(p_tier text, p_cfg jsonb)
returns integer
language sql
immutable
set search_path = ''
as $$
  select coalesce((select (x.n - 1)::integer from jsonb_array_elements(coalesce(p_cfg -> 'ladder', '[]'::jsonb))
                                                  with ordinality x(r, n) where x.r ->> 'tier' = p_tier), 0);
$$;

create or replace function public.player_stock_tier_label(p_tier text, p_cfg jsonb)
returns text
language sql
immutable
set search_path = ''
as $$
  select coalesce((select x.r ->> 'label' from jsonb_array_elements(coalesce(p_cfg -> 'ladder', '[]'::jsonb)) x(r)
                    where x.r ->> 'tier' = p_tier), p_tier);
$$;

-- ---------------------------------------------------------------------------
-- D. The periodic check
-- ---------------------------------------------------------------------------
create or replace function public.player_stock_tiers_run(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now     timestamptz := coalesce(p_now, now());
  v_cfg     jsonb := public.player_stock_tier_cfg();
  r         record;
  v_cap     bigint;
  v_hours   double precision;
  v_next    text;
  v_up      boolean;
  v_label   text;
  v_head    text;
  v_body    text;
  v_checked integer := 0;
  v_changed integer := 0;
begin
  for r in select c.id, c.name, c.tier::text as tier, c.security_id, c.sector_key, pc.founder_id,
                  st.changed_at, st.peak_tier
             from public.companies c
             join public.player_companies pc on pc.company_id = c.id
             left join public.player_stock_tiers st on st.company_id = c.id
            where not c.is_ai and c.phase = 'listed' and c.security_id is not null
            order by c.id
  loop
    v_checked := v_checked + 1;
    v_cap := greatest(0, coalesce(public.company_worth_cents(r.id), 0));
    v_hours := case when r.changed_at is null then null else extract(epoch from (v_now - r.changed_at)) / 3600.0 end;
    v_next := public.player_stock_tier_next(r.tier, v_cap, v_hours, v_cfg);
    insert into public.player_stock_tiers (company_id, tier, changed_at, checked_at, market_cap_cents, peak_tier)
    values (r.id, coalesce(r.tier, v_next), null, v_now, v_cap, coalesce(r.tier, v_next))
    on conflict (company_id) do update set checked_at = excluded.checked_at, market_cap_cents = excluded.market_cap_cents;
    continue when v_next is not distinct from r.tier;

    v_up := public.player_stock_tier_rung(v_next, v_cfg) > public.player_stock_tier_rung(r.tier, v_cfg);
    update public.companies set tier = v_next::public.company_tier, updated_at = now() where id = r.id;
    update public.player_stock_tiers
       set tier = v_next, changed_at = v_now,
           peak_tier = case when public.player_stock_tier_rung(v_next, v_cfg) > public.player_stock_tier_rung(peak_tier, v_cfg)
                            then v_next else peak_tier end
     where company_id = r.id;
    v_changed := v_changed + 1;

    v_label := public.player_stock_tier_label(v_next, v_cfg);
    if v_up then
      v_head := r.name || ' steigt in den ' || v_label || ' auf';
      v_body := 'Börsenwert ' || public.format_eur(v_cap) || ': Die Aktie spielt jetzt in einer höheren Klasse. '
                || 'Große Orders bewegen den Kurs weniger, mehr Anleger schauen hin.';
    else
      v_head := r.name || ' fällt zurück in den ' || v_label;
      v_body := 'Börsenwert ' || public.format_eur(v_cap) || ': Die Aktie verliert ihre Klasse. '
                || 'Orders bewegen den Kurs wieder stärker.';
    end if;
    -- stock news (Mr. Doodle reads news_items)
    insert into public.news_items (category, headline, body, importance, security_id, company_id, sector_key, published_at)
    values ('market', v_head, v_body, case when v_up then 2 else 1 end, r.security_id, r.id, r.sector_key, v_now);
    perform public.social_notify(r.founder_id, 'stock_tier', v_head, v_body,
                                 jsonb_build_object('company_id', r.id, 'tier', v_next, 'up', v_up, 'market_cap_cents', v_cap),
                                 '/company', 'stock_tier:' || r.id::text || ':' || v_next || ':' || to_char(v_now, 'YYYYMMDDHH24MI'));
    perform public.company_system_message(r.id, v_head || '.');
  end loop;
  return jsonb_build_object('checked', v_checked, 'changed', v_changed);
end;
$$;
comment on function public.player_stock_tiers_run(timestamptz) is
  'Internal, cron every 10 minutes (ADR-218): stock tier of every listed player company from its market cap, with '
  'hysteresis; on a change: companies.tier, stock news and a note to the founder.';

-- ---------------------------------------------------------------------------
-- E. Grants and the cron job
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.company_player_tier_guard()', 'public.player_stock_tier_cfg()',
    'public.player_stock_tier_next(text, numeric, double precision, jsonb)', 'public.player_stock_tier_rung(text, jsonb)',
    'public.player_stock_tier_label(text, jsonb)', 'public.player_stock_tiers_run(timestamptz)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
  grant execute on function public.player_stock_tiers_run(timestamptz) to service_role;
  grant execute on function public.player_stock_tier_next(text, numeric, double precision, jsonb) to service_role;
end;
$$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'nexa-player-stock-tiers';
    perform cron.schedule('nexa-player-stock-tiers', '*/10 * * * *', 'select public.player_stock_tiers_run()');
  end if;
end;
$$;

-- ===== supabase/updates/20261204011400_nexamon_pack_buy_limits.sql =====
-- ===== idempotent copy of migrations/20261204011400_nexamon_pack_buy_limits.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 011400 · Buying packs back to back: a multi-buy is one action (ADR-182 Nachtrag)
-- =============================================================================
-- Until now every pack of a multi-buy (buy_nexamon_packs, 10 packs) took one hit of packs.perMinute (20) in the
-- fixed minute window: after two buys of 10 every further buy failed with rate_limited ("zu viele Aktionen").
-- * api_rate_limited(p_window_seconds): raises rate_limited (NX004) with the seconds until the current window ends
--   as the error detail; the client shows "Kurz warten: noch X s".
-- * nexamon_buy_pack_as(p_player, p_request_id, p_set, p_count): the purchase of one pack (latest buy_nexamon_pack,
--   8100: release, pack sale price, payment, pulls, missions), internal. With p_count it takes the hit of
--   packs.perMinute itself (a single buy), without it the caller has counted.
-- * buy_nexamon_pack (latest: 8100): the single buy, unchanged apart from the wait in the error.
-- * buy_nexamon_packs (latest: 7240): ONE hit of packs.perMinute for the whole buy (an action, like a single buy)
--   and one hit per pack of packs.maxPacksPerMinute (abuse cap on volume, default 100 packs a minute).
-- Idempotent: runs unchanged as supabase/updates/20261204011400_nexamon_pack_buy_limits.sql.

create or replace function public.api_rate_limited(p_window_seconds integer)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_now  numeric := extract(epoch from clock_timestamp());
  v_wait integer;
begin
  -- rate_limit_hit counts in fixed windows of p_window_seconds: the next one starts at the next multiple
  v_wait := greatest(1, ceil(p_window_seconds - mod(v_now, p_window_seconds))::integer);
  raise exception using errcode = 'NX004', message = 'rate_limited', detail = 'retry_after=' || v_wait;
end;
$$;
comment on function public.api_rate_limited(integer) is
  'Raises the API error rate_limited (NX004) with detail retry_after=<seconds until the fixed window of '
  'rate_limit_hit ends>; the client shows the wait.';

create or replace function public.nexamon_buy_pack_as(p_player uuid, p_request_id uuid, p_set text, p_count boolean)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  cfg      jsonb := public.nexamon_cfg();
  v_player uuid := p_player;
  v_replay jsonb;
  v_now    timestamptz := public.game_now();
  v_price  bigint;
  v_cash   bigint;
  v_pack   uuid := gen_random_uuid();
  v_cards  jsonb;
  r        record;
begin
  perform public.nexamon_require_unlock(v_player);
  if p_request_id is null or p_set is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_nexamon_pack');
  if v_replay is not null then
    return v_replay;
  end if;
  perform public.nexamon_sync(v_now);
  v_price := (cfg #>> array['sets', p_set, 'packPriceCents'])::bigint;
  if v_price is null or v_price < 0 or not exists (select 1 from public.nexamon_cards k where k.set_key = p_set and k.in_catalogue) then
    perform public.api_error('nexamon_unknown');
  end if;
  if not public.nexamon_set_released(p_set, public.game_now()) then
    perform public.api_error('nexamon_set_not_released');
  end if;
  -- ADR-193: a running pack sale of this set
  v_price := public.news_promo_pack_price(p_set, v_price, v_now);
  if p_count and not public.rate_limit_hit(v_player, 'nexamon_pack', coalesce((cfg #>> '{packs,perMinute}')::integer, 20), 60) then
    perform public.api_rate_limited(60);
  end if;
  v_cash := public.lock_player_accounts(v_player);
  if v_cash < v_price then
    perform public.api_error('insufficient_funds');
  end if;
  if v_price > 0 then
    perform public.ledger_transfer(public.ledger_player_account(v_player, 'player_cash'), public.ledger_system_account('households'),
                                   v_price, 'nexamon_pack', 'Booster gekauft: ' || coalesce(cfg #>> array['sets', p_set, 'name'], p_set),
                                   'nexamon_pack', v_pack, 'nexamon:pack:' || v_player::text || ':' || p_request_id::text, v_player,
                                   jsonb_build_object('set', p_set, 'price_cents', v_price));
  end if;
  v_cards := public.nexamon_open_pack(p_set, v_player, null, v_pack, v_now);
  insert into public.nexamon_packs (id, player_id, set_key, price_cents, cards, opened_at)
  values (v_pack, v_player, p_set, v_price, v_cards, v_now);
  update public.nexamon_set_state set player_packs_opened = player_packs_opened + 1 where set_key = p_set;
  perform public.mission_event(v_player, 'nexamon_pack', 1, null);
  for r in select x ->> 'rarity' as rarity from jsonb_array_elements(v_cards) x loop
    if public.nexamon_rarity_rank(r.rarity) >= 1 then
      perform public.mission_event(v_player, 'nexamon_rare', 1, null);
    end if;
    if public.nexamon_rarity_rank(r.rarity) >= 2 then
      perform public.mission_event(v_player, 'nexamon_ultra', 1, null);
    end if;
  end loop;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'pack_id', v_pack, 'set', p_set, 'price_cents', v_price, 'cards', v_cards,
    'packs_opened', (select count(*) from public.nexamon_packs p where p.player_id = v_player and p.set_key = p_set)));
end;
$function$;
comment on function public.nexamon_buy_pack_as(uuid, uuid, text, boolean) is
  'Internal: one booster pack bought and opened for a player (buy_nexamon_pack); p_count: take the packs.perMinute hit.';

create or replace function public.buy_nexamon_pack(p_request_id uuid, p_set text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
begin
  return public.nexamon_buy_pack_as(public.require_player(), p_request_id, p_set, true);
end;
$function$;
comment on function public.buy_nexamon_pack(uuid, text) is
  'RPC: buys and opens a booster pack of a set (money to the households): five pulls in slot order with condition, '
  'population number and whether the card is new to the player (ADR-165); errors nexamon_locked, invalid_argument, '
  'nexamon_unknown, nexamon_set_not_released, rate_limited (detail retry_after=<s>), insufficient_funds.';

create or replace function public.buy_nexamon_packs(p_request_id uuid, p_set text, p_count integer)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.nexamon_cfg();
  v_player uuid;
  v_replay jsonb;
  v_packs  jsonb := '[]'::jsonb;
  v_one    jsonb;
  v_total  bigint := 0;
  v_ok     boolean := true;
  i        integer;
begin
  v_player := public.require_player();
  perform public.nexamon_require_unlock(v_player);
  if p_request_id is null or p_set is null or p_count is null or p_count < 1
     or p_count > coalesce((cfg #>> '{packs,maxPerBuy}')::integer, 10) then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'buy_nexamon_packs');
  if v_replay is not null then
    return v_replay;
  end if;
  -- one action for the whole buy, and every pack against the volume cap
  if not public.rate_limit_hit(v_player, 'nexamon_pack', coalesce((cfg #>> '{packs,perMinute}')::integer, 20), 60) then
    perform public.api_rate_limited(60);
  end if;
  for i in 1 .. p_count loop
    v_ok := public.rate_limit_hit(v_player, 'nexamon_pack_volume', coalesce((cfg #>> '{packs,maxPacksPerMinute}')::integer, 100), 60)
            and v_ok;
  end loop;
  if not v_ok then
    perform public.api_rate_limited(60);
  end if;
  for i in 1 .. p_count loop
    v_one := public.nexamon_buy_pack_as(v_player, md5(p_request_id::text || ':pack:' || i)::uuid, p_set, false);
    v_packs := v_packs || jsonb_build_array(v_one);
    v_total := v_total + coalesce((v_one ->> 'price_cents')::bigint, 0);
  end loop;
  return public.request_complete(v_player, p_request_id, jsonb_build_object(
    'set', p_set, 'count', p_count, 'price_cents', v_total, 'packs', v_packs));
end;
$$;
comment on function public.buy_nexamon_packs(uuid, text, integer) is
  'RPC: buys 1..packs.maxPerBuy booster packs of a set at once (ADR-182), each like buy_nexamon_pack (payment, pulls), '
  'all or nothing -> {set, count, price_cents, packs: [buy_nexamon_pack answers in order]}; idempotent. The buy is one '
  'action of packs.perMinute; its packs count against packs.maxPacksPerMinute. Errors as buy_nexamon_pack and '
  'invalid_argument.';

do $do$
begin
  revoke all on function public.api_rate_limited(integer) from public, anon, authenticated;
  revoke all on function public.nexamon_buy_pack_as(uuid, uuid, text, boolean) from public, anon, authenticated;
  revoke all on function public.buy_nexamon_pack(uuid, text) from public, anon;
  grant execute on function public.buy_nexamon_pack(uuid, text) to authenticated;
  revoke all on function public.buy_nexamon_packs(uuid, text, integer) from public, anon;
  grant execute on function public.buy_nexamon_packs(uuid, text, integer) to authenticated;
end;
$do$;

-- ===== supabase/updates/20261204011500_nexamon_ai_top_cards.sql =====
-- ===== idempotent copy of migrations/20261204011500_nexamon_ai_top_cards.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 011500 · Nexamon: the AI buys the most expensive cards at market value too (ADR-195, Nachtrag)
-- =============================================================================
-- Owner: "Die KI soll auch die teuersten Karten auf dem Markt für Marktpreis oder weniger kaufen."
-- * nexamon_ai_buy_chance_bps(): at or below the copy's value 10 000 for every rarity, One of One and uranium
--   included (raw or slab, Black Label too); above the value unchanged (ADR-195), never for those two rarities.
-- * nexamon_run_due(), section 2: a One of One or uranium card goes to the game's vault (instantSell.vaultOwner,
--   "NEXA-Tresor"; the AI guard allows exactly that owner). If the households' cash cannot pay a buy at or below
--   the value, the treasury tops them up by exactly the shortfall (ledger 'transfer' treasury -> households, sum 0,
--   key nexamon:ai:fund:<listing>:<run>) as long as it keeps ai.treasuryFloorCents; otherwise the buy is logged
--   (raise log, result ai_unaffordable) and the listing stays for the next run. A buy that errors is logged and
--   skipped (result ai_failed) instead of rolling back the whole minute job.
-- * nexamon_run_due(), section 2b: the vault puts a copy it held at least vault.minHoldHours back on sale with a
--   chance of vault.relistChancePerDayBps per day, at value + vault.premiumMinBps..premiumMaxBps
--   (nexamon_vault_ask_cents, nexamonVaultAskCents), at most vault.maxListed at a time; withdrawn after listHours.
-- * nexamon_ai_restock() never lists a vault copy (slabs included); nexamon_ai_reset() keeps the vault's listings.
-- Latest definitions copied: nexamon_ai_buy_chance_bps / nexamon_run_due (8500), nexamon_ai_restock (7100),
-- nexamon_ai_reset (8600).
-- Idempotent (identical copy in supabase/updates/).
-- =============================================================================

-- nexamonAiBuyChanceBps: 10 000 at or below the value (every rarity); above it rare, never for the vault rarities
create or replace function public.nexamon_ai_buy_chance_bps(p_price bigint, p_value bigint, p_condition text, p_grade double precision,
                                                            p_rarity text, p_population bigint)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  ai      jsonb := public.nexamon_cfg() -> 'ai';
  v_min   bigint;
  v_pop   bigint;
  v_full  bigint;
  v_max   bigint;
  v_share bigint;
begin
  if coalesce(p_price, 0) <= 0 then
    return 0;
  end if;
  if p_price <= p_value then
    return 10000;
  end if;
  -- One of Ones and uranium: the vault buys at or below the value only (ADR-195, Nachtrag)
  if coalesce(ai -> 'excludedRarities', '[]'::jsonb) ? p_rarity then
    return 0;
  end if;
  v_max := floor(p_value::numeric * (10000 + public.nexamon_ai_premium_bps(p_condition, p_grade)) / 10000)::bigint;
  if p_price > v_max then
    return 0;
  end if;
  v_min := coalesce((ai ->> 'buyChanceMinShareBps')::bigint, 10000);
  v_pop := floor((10000 - v_min)::numeric * public.nexamon_popularity_bps(p_rarity, p_population) / 10000)::bigint;
  v_full := floor(coalesce((ai ->> 'buyChanceBps')::numeric, 0) * (v_min + v_pop) / 10000)::bigint;
  v_share := 10000 - floor((10000 - coalesce((ai ->> 'atMaxChanceBps')::numeric, 0)) * (p_price - p_value) / (v_max - p_value))::bigint;
  return floor(v_full::numeric * v_share / 10000)::integer;
end;
$$;

-- nexamonVaultAskCents: the vault's ask, value + premiumMinBps .. premiumMaxBps (u in [0, 1))
create or replace function public.nexamon_vault_ask_cents(p_value bigint, p_u double precision)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(1, floor(coalesce(p_value, 0)::numeric
           * (10000 + coalesce((v ->> 'premiumMinBps')::integer, 1500)
              + floor((coalesce((v ->> 'premiumMaxBps')::integer, 2500) - coalesce((v ->> 'premiumMinBps')::integer, 1500))
                      * least(1, greatest(0, coalesce(p_u, 0)))::numeric)) / 10000)::bigint)
    from (select coalesce(public.nexamon_cfg() -> 'vault', '{}'::jsonb) as v) c;
$$;

-- The AI sellers offer up to ai.listedPerCard raw copies of a card (p_extra more, for a legendary) and every slab
-- whose hold has passed; the vault's copies never (it relists on its own, nexamon_run_due section 2b).
create or replace function public.nexamon_ai_restock(p_card text, p_now timestamptz, p_extra integer default 0)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  k        public.nexamon_cards;
  v_vault  text := coalesce(public.nexamon_cfg() #>> '{instantSell,vaultOwner}', 'NEXA-Tresor');
  v_limit  integer;
  v_listed integer;
  v_n      integer := 0;
  r        record;
begin
  select * into k from public.nexamon_cards where card_key = p_card;
  if k.card_key is null then
    return 0;
  end if;
  v_limit := coalesce((public.nexamon_cfg() #>> array['ai', 'listedPerCard', k.rarity])::integer, 0) + greatest(0, coalesce(p_extra, 0));
  select count(*) into v_listed from public.nexamon_listings l join public.nexamon_copies c on c.id = l.copy_id
   where l.card_key = p_card and l.seller_ai is not null and l.seller_ai is distinct from v_vault and c.grade is null;
  for r in select c.id, c.ai_owner, c.condition, c.grade from public.nexamon_copies c
            where c.card_key = p_card and c.ai_owner is not null and c.ai_owner is distinct from v_vault and c.grade is null
              and not exists (select 1 from public.nexamon_listings l where l.copy_id = c.id)
            order by c.acquired_at, c.serial
            limit greatest(0, v_limit - v_listed) loop
    insert into public.nexamon_listings (copy_id, card_key, seller_ai, price_cents, created_at)
    values (r.id, p_card, r.ai_owner,
            public.nexamon_ai_ask_cents(public.nexamon_copy_value_cents(k.value_e4, r.condition, r.grade, k.card_key)), p_now);
    v_n := v_n + 1;
  end loop;
  -- slabs never leave circulation: once held long enough, the AI lists every one of them
  for r in select c.id, c.ai_owner, c.condition, c.grade from public.nexamon_copies c
            where c.card_key = p_card and c.ai_owner is not null and c.ai_owner is distinct from v_vault
              and c.grade is not null and c.grading_until is null
              and coalesce(c.ai_hold_until, '-infinity'::timestamptz) <= p_now
              and not exists (select 1 from public.nexamon_listings l where l.copy_id = c.id)
            order by c.acquired_at, c.serial loop
    insert into public.nexamon_listings (copy_id, card_key, seller_ai, price_cents, created_at)
    values (r.id, p_card, r.ai_owner,
            public.nexamon_ai_ask_cents(public.nexamon_copy_value_cents(k.value_e4, r.condition, r.grade, k.card_key)), p_now);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;

-- Every ai.listingResetHours: the AI's offers go (the vault's stay), its raw stock above the cap is retired (slabs
-- and the vault never), then it lists again, held slabs whose time has come included.
create or replace function public.nexamon_ai_reset(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  ai        jsonb := public.nexamon_cfg() -> 'ai';
  v_vault   text := coalesce(public.nexamon_cfg() #>> '{instantSell,vaultOwner}', 'NEXA-Tresor');
  v_now     timestamptz := coalesce(p_now, public.game_now());
  v_hours   integer := coalesce((public.nexamon_cfg() #>> '{ai,listingResetHours}')::integer, 0);
  v_last    timestamptz;
  v_deleted integer := 0;
  v_retired integer := 0;
  v_listed  integer := 0;
  r         record;
begin
  if v_hours <= 0 then
    return jsonb_build_object('skipped', 'off');
  end if;
  perform pg_advisory_xact_lock(7311652);
  select m.ai_reset_at into v_last from public.nexamon_meta m where m.id;
  if v_last is not null and v_now < v_last + make_interval(hours => v_hours) then
    return jsonb_build_object('skipped', 'not due');
  end if;
  delete from public.nexamon_listings where seller_ai is not null and seller_ai is distinct from v_vault;
  get diagnostics v_deleted = row_count;
  -- retire the raw stock above the cap, the newest copies first; graded copies and the vault are never retired
  with ranked as (
    select c.id, row_number() over (partition by c.card_key order by c.acquired_at, c.serial) as n,
           coalesce((ai #>> array['stockCap', k.rarity])::integer, 1000000) as cap
      from public.nexamon_copies c join public.nexamon_cards k on k.card_key = c.card_key
     where c.ai_owner is not null and c.grade is null and c.grading_until is null
       and c.ai_owner is distinct from v_vault
  )
  delete from public.nexamon_copies c using ranked x where x.id = c.id and x.n > x.cap;
  get diagnostics v_retired = row_count;
  for r in select distinct c.card_key from public.nexamon_copies c
            where c.ai_owner is not null and c.ai_owner is distinct from v_vault loop
    v_listed := v_listed + public.nexamon_ai_restock(r.card_key, v_now);
  end loop;
  insert into public.nexamon_meta (id, ai_reset_at) values (true, v_now)
  on conflict (id) do update set ai_reset_at = excluded.ai_reset_at;
  return jsonb_build_object('deleted', v_deleted, 'retired', v_retired, 'listed', v_listed);
end;
$$;
comment on function public.nexamon_ai_reset(timestamptz) is
  'Internal (cron nexa-nexamon-ai-reset): every ai.listingResetHours the AI''s listings are removed (the vault''s '
  'stay), its raw stock above ai.stockCap retired (slabs and the game''s vault never), and it lists again at the '
  'current value, held slabs whose time has come included (ADR-174, ADR-165, ADR-196, ADR-195 Nachtrag).';

-- The minute job (latest definition from 8500; section 2 extended, section 2b new).
create or replace function public.nexamon_run_due(p_now timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg       jsonb := public.nexamon_cfg();
  ai        jsonb := public.nexamon_cfg() -> 'ai';
  vt        jsonb := coalesce(public.nexamon_cfg() -> 'vault', '{}'::jsonb);
  v_now     timestamptz := coalesce(p_now, public.game_now());
  v_day     timestamptz := ((coalesce(p_now, public.game_now()) at time zone 'Europe/Berlin')::date)::timestamp
                           at time zone 'Europe/Berlin';
  v_house   uuid := public.ledger_system_account('households');
  v_state   uuid := public.ledger_system_account('treasury');
  v_names   jsonb := coalesce(public.nexamon_cfg() #> '{ai,sellers}', '[]'::jsonb);
  v_excl    jsonb := coalesce(public.nexamon_cfg() #> '{ai,excludedRarities}', '["one_of_one"]'::jsonb);
  v_vault   text := coalesce(public.nexamon_cfg() #>> '{instantSell,vaultOwner}', 'NEXA-Tresor');
  v_floor   bigint := coalesce((public.nexamon_cfg() #>> '{ai,treasuryFloorCents}')::bigint, 0);
  v_graded  integer;
  v_packs   integer := 0;
  v_bought  integer := 0;
  v_unaff   integer := 0;
  v_failed  integer := 0;
  v_funded  bigint := 0;
  v_vlisted integer := 0;
  v_relist  integer := 0;
  v_steps   integer := 0;
  v_due     integer;
  v_n       integer;
  v_per     numeric;
  v_pulls   jsonb;
  v_cash    bigint;
  v_tcash   bigint;
  v_short   bigint;
  v_value   bigint;
  v_spent   bigint;
  v_chance  integer;
  v_name    text;
  r         record;
  x         record;
  i         integer;
begin
  if cfg = '{}'::jsonb or ai is null or jsonb_array_length(v_names) = 0 then
    return jsonb_build_object('skipped', 'no config');
  end if;
  perform public.nexamon_sync(v_now);
  v_graded := public.nexamon_finish_gradings(null, v_now);

  -- 1. the AI opens packs: its pulls raise the populations and go into its stock
  for r in select s.* from public.nexamon_set_state s order by s.set_key for update loop
    v_per := coalesce((ai #>> array['packsPerHour', r.set_key])::numeric, 0);
    continue when v_per <= 0 or not exists (select 1 from public.nexamon_cards k where k.set_key = r.set_key and k.in_catalogue);
    v_due := floor(extract(epoch from (v_now - r.ai_packs_at)) / 3600 * v_per)::integer;
    continue when v_due < 1;
    v_n := least(v_due, coalesce((ai ->> 'maxPacksPerRun')::integer, 5));
    for i in 1 .. v_n loop
      v_name := v_names ->> floor(random() * jsonb_array_length(v_names))::integer;
      v_pulls := public.nexamon_open_pack(r.set_key, null, v_name, null, v_now);
      for x in select distinct p ->> 'card_key' as card_key from jsonb_array_elements(v_pulls) p loop
        perform public.nexamon_ai_restock(x.card_key, v_now);
      end loop;
    end loop;
    v_packs := v_packs + v_n;
    update public.nexamon_set_state
       set ai_packs_opened = ai_packs_opened + v_n,
           -- a long pause is not caught up on: the backlog is dropped
           ai_packs_at = case when v_due > v_n * 20 then v_now else ai_packs_at + make_interval(secs => v_n * 3600 / v_per) end
     where set_key = r.set_key;
  end loop;

  -- 2. AI collectors buy player listings (nexamonAiBuyChanceBps, ADR-195 and Nachtrag): at or below the copy's value
  --    (with the card, as the UI shows it) always, on this run, whatever the price and rarity and without a budget;
  --    One of Ones and uranium cards go to the game's vault. Above the value up to value x (1 + premium, at most
  --    ai.maxPremiumBps) rarely, more often for popular cards, never for the vault rarities. Fair listings first, then
  --    better copies; only buys above the value check the households' budget per set and Berlin day. A buy at or below
  --    the value the households cannot pay is topped up by the treasury (shortfall only, down to ai.treasuryFloorCents);
  --    if even that is not enough, it is logged and retried on the next run. nexamon_sell() keys each buy by the
  --    listing (no double buys).
  for r in select q.* from (
             select l.id, l.price_cents, l.card_key, c.condition, c.grade, k.value_e4, k.rarity, k.population, k.set_key,
                    public.nexamon_copy_value_cents(k.value_e4, c.condition, c.grade, c.card_key) as copy_value,
                    public.nexamon_copy_factor_bps(c.condition, c.grade, c.card_key) as factor
               from public.nexamon_listings l
               join public.nexamon_copies c on c.id = l.copy_id
               join public.nexamon_cards k on k.card_key = l.card_key
              where l.seller_id is not null) q
            order by (q.price_cents <= q.copy_value) desc, q.factor desc, random()
            limit 500 loop
    exit when v_bought >= coalesce((ai ->> 'maxBuysPerRun')::integer, 100);
    continue when not exists (select 1 from public.nexamon_listings l where l.id = r.id);
    v_value := r.copy_value;
    v_chance := public.nexamon_ai_buy_chance_bps(r.price_cents, v_value, r.condition, r.grade, r.rarity, r.population);
    continue when v_chance <= 0;
    continue when v_chance < 10000 and random() * 10000 >= v_chance;
    if r.price_cents > v_value then
      select coalesce(sum(s.price_cents), 0) into v_spent
        from public.nexamon_sales s join public.nexamon_cards k on k.card_key = s.card_key
       where s.kind = 'ai_buy' and s.at >= v_day and k.set_key = r.set_key;
      continue when v_spent + r.price_cents
                    > coalesce((ai ->> 'dailyBudgetPacks')::bigint, 0) * coalesce((cfg #>> array['sets', r.set_key, 'packPriceCents'])::bigint, 0);
    end if;
    begin
      select a.balance_cents into v_cash from public.ledger_accounts a where a.id = v_house;
      if coalesce(v_cash, 0) < r.price_cents then
        -- premium buys are never funded; a buy at or below the value is (nexamonAiFundingCents)
        continue when r.price_cents > v_value;
        v_short := r.price_cents - greatest(0, coalesce(v_cash, 0));
        select a.balance_cents into v_tcash from public.ledger_accounts a where a.id = v_state;
        if coalesce(v_tcash, 0) - v_short < v_floor then
          v_unaff := v_unaff + 1;
          raise log 'nexamon_run_due: AI buy of listing % (% cents, % %) not affordable: households % cents, treasury % cents, floor % cents; retried next run',
            r.id, r.price_cents, r.card_key, r.rarity, coalesce(v_cash, 0), coalesce(v_tcash, 0), v_floor;
          continue;
        end if;
        perform public.ledger_transfer(v_state, v_house, v_short, 'transfer',
                                       'Staatskasse stockt die Haushalte für einen Nexamon-Kauf zum Marktwert auf',
                                       'nexamon_listing', r.id,
                                       'nexamon:ai:fund:' || r.id::text || ':' || extract(epoch from v_now)::bigint::text, null,
                                       jsonb_build_object('card_key', r.card_key, 'price_cents', r.price_cents,
                                                          'households_cents', coalesce(v_cash, 0), 'shortfall_cents', v_short));
        v_funded := v_funded + v_short;
      end if;
      v_name := case when v_excl ? r.rarity then v_vault
                     else v_names ->> floor(random() * jsonb_array_length(v_names))::integer end;
      perform public.nexamon_sell(r.id, null, v_name, 'nexamon:ai:' || r.id::text, v_now);
      v_bought := v_bought + 1;
    exception when others then
      -- one broken buy must not roll back the whole minute job; the listing stays and is tried again
      v_failed := v_failed + 1;
      raise warning 'nexamon_run_due: AI buy of listing % failed: % (%)', r.id, sqlerrm, sqlstate;
    end;
  end loop;

  -- 2b. the game's vault puts a One of One or uranium card back on the market now and then, above its value
  delete from public.nexamon_listings l
   where l.seller_ai = v_vault
     and l.created_at <= v_now - make_interval(hours => coalesce((vt ->> 'listHours')::integer, 24));
  select count(*) into v_vlisted from public.nexamon_listings l where l.seller_ai = v_vault;
  if coalesce((vt ->> 'relistChancePerDayBps')::integer, 0) > 0 then
    for r in select c.id, c.card_key, c.condition, c.grade, k.value_e4
               from public.nexamon_copies c join public.nexamon_cards k on k.card_key = c.card_key
              where c.ai_owner = v_vault and c.grading_until is null
                and c.acquired_at <= v_now - make_interval(hours => coalesce((vt ->> 'minHoldHours')::integer, 72))
                and not exists (select 1 from public.nexamon_listings l where l.copy_id = c.id)
              order by random() loop
      exit when v_vlisted >= coalesce((vt ->> 'maxListed')::integer, 0);
      continue when random() * 10000 * 1440 >= (vt ->> 'relistChancePerDayBps')::numeric;
      insert into public.nexamon_listings (copy_id, card_key, seller_ai, price_cents, created_at)
      values (r.id, r.card_key, v_vault,
              public.nexamon_vault_ask_cents(public.nexamon_copy_value_cents(r.value_e4, r.condition, r.grade, r.card_key), random()),
              v_now);
      v_vlisted := v_vlisted + 1;
      v_relist := v_relist + 1;
    end loop;
  end if;

  -- 3. supply against demand, once per pressure.everyMinutes and card
  for r in select k.card_key from public.nexamon_cards k
            where k.in_catalogue
              and (k.pressure_at is null
                   or k.pressure_at <= v_now - make_interval(mins => coalesce((cfg #>> '{value,pressure,everyMinutes}')::integer, 60)))
            order by k.pressure_at nulls first, k.card_key
            limit coalesce((cfg #>> '{value,pressure,perRun}')::integer, 80) loop
    perform public.nexamon_pressure_step(r.card_key, v_now);
    v_steps := v_steps + 1;
  end loop;

  delete from public.nexamon_value_points
   where at < v_now - make_interval(days => coalesce((cfg #>> '{market,historyDays}')::integer, 60) + 1);
  return jsonb_build_object('graded', v_graded, 'ai_packs', v_packs, 'ai_bought', v_bought, 'ai_unaffordable', v_unaff,
                            'ai_failed', v_failed, 'ai_funded_cents', v_funded, 'vault_listed', v_relist,
                            'value_steps', v_steps);
end;
$$;
comment on function public.nexamon_run_due(timestamptz) is
  'Job (cron nexa-nexamon, every minute; ADR-165, ADR-195 and Nachtrag): finishes gradings, opens the AI''s packs, '
  'lets AI collectors buy player listings (at or below the value always, whatever the price and rarity, One of Ones '
  'and uranium into the game''s vault, a shortfall of the households funded by the treasury; above it rarely, at '
  'most +15 %), lets the vault relist now and then above the value, moves the values by supply and demand.';

do $do$
declare
  f text;
begin
  foreach f in array array[
    'public.nexamon_ai_buy_chance_bps(bigint, bigint, text, double precision, text, bigint)',
    'public.nexamon_vault_ask_cents(bigint, double precision)',
    'public.nexamon_ai_restock(text, timestamptz, integer)',
    'public.nexamon_ai_reset(timestamptz)',
    'public.nexamon_run_due(timestamptz)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
end;
$do$;

commit;
